    "effectZh": "[登场时]\n查看自己山札上方 3 张，公开卡名包含「吉纳斯」的角色卡片最多 1 张并加入手牌。将剩余部分按任意顺序置于山札下方。若成功加入手牌，则将自己手牌中的 1 张置入场外区域。",
